class Solution {
    public void merge(int[] nums1, int m, int[] nums2, int n) {
        int p1 = m-1, p2 = n-1, p3 = m+n-1;
        while (p1 >= 0 && p2 >= 0) {
            if (nums1[p1] > nums2[p2]) nums1[p3--] = nums1[p1--];
            else nums1[p3--] = nums2[p2--];
        }
        while (p2 >= 0) nums1[p3--] = nums2[p2--];
    }
}

class Solution:
    def threeSum(self, nums):
        nums.sort(); result = []
        for i in range(len(nums) - 2):
            if i >= 1 and nums[i] == nums[i-1]: continue
            j, k = i+1, len(nums)-1
            target = -nums[i]
            while j < k:
                if nums[j]+nums[k] == target:
                    result.append([nums[i],nums[j],nums[k]])
                    while j<k and nums[j]==nums[j+1]: j+=1
                    while j<k and nums[k]==nums[k-1]: k-=1
                    j+=1; k-=1
                elif nums[j]+nums[k] < target: j+=1
                else: k-=1
        return result

class Solution {
    public int minCost(int[][] costs) {
        for (int i = costs.length-2; i >= 0; i--) {
            costs[i][0] += Math.min(costs[i+1][1], costs[i+1][2]);
            costs[i][1] += Math.min(costs[i+1][0], costs[i+1][2]);
            costs[i][2] += Math.min(costs[i+1][0], costs[i+1][1]);
        }
        return Math.min(costs[0][0], Math.min(costs[0][1], costs[0][2]));
    }
}

class Solution {
    public int rob(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        dp[0] = nums[0];
        if (n > 1) dp[1] = Math.max(nums[0], nums[1]);
        for (int i = 2; i < n; i++)
            dp[i] = Math.max(dp[i-1], dp[i-2] + nums[i]);
        return dp[n-1];
    }
}

class Solution:
    def partition(self, s):
        self.result = []
        self.backtrack(s, 0, [])
        return self.result

    def backtrack(self, s, pivot, path):
        if pivot == len(s): self.result.append(path[:]); return
        for i in range(pivot, len(s)):
            sub = s[pivot:i+1]
            if sub == sub[::-1]:
                path.append(sub)
                self.backtrack(s, i+1, path)
                path.pop()

class Solution:
    def exist(self, board, word):
        m, n = len(board), len(board[0])
        def dfs(i, j, k):
            if k == len(word): return True
            if i<0 or i>=m or j<0 or j>=n or board[i][j] != word[k]: return False
            tmp, board[i][j] = board[i][j], '#'
            found = any(dfs(i+dx,j+dy,k+1) for dx,dy in [(0,1),(1,0),(0,-1),(-1,0)])
            board[i][j] = tmp
            return found
        return any(dfs(i,j,0) for i in range(m) for j in range(n))

