class Solution:
    def searchRange(self, nums, target):
        def bs(left_bias):
            lo, hi, idx = 0, len(nums)-1, -1
            while lo <= hi:
                mid = (lo+hi)//2
                if nums[mid] == target:
                    idx = mid
                    if left_bias: hi = mid-1
                    else: lo = mid+1
                elif nums[mid] < target: lo = mid+1
                else: hi = mid-1
            return idx
        return [bs(True), bs(False)]

