class Solution:
    def isCousins(self, root, x, y):
        q = deque([root])
        while q:
            level, sibling = set(), False
            for _ in range(len(q)):
                node = q.popleft()
                level.add(node.val)
                if node.left and node.right:
                    vals={node.left.val,node.right.val}
                    if x in vals and y in vals: sibling=True
                if node.left: q.append(node.left)
                if node.right: q.append(node.right)
            if x in level and y in level: return not sibling
        return False

