class Trie:
    def __init__(self): self.root=TrieNode()
    def insert(self, word):
        node=self.root
        for c in word:
            i=ord(c)-ord('a')
            if not node.children[i]: node.children[i]=TrieNode()
            node=node.children[i]
        node.isEnd=True
    def search(self, word):
        node=self.root
        for c in word:
            i=ord(c)-ord('a')
            if not node.children[i]: return False
            node=node.children[i]
        return node.isEnd
    def startsWith(self, prefix):
