class Solution:
    def canFinish(self, numCourses, prerequisites):
        adj = [[] for _ in range(numCourses)]
        ind = [0]*numCourses
        for a,b in prerequisites: adj[b].append(a); ind[a]+=1
        q = deque(i for i in range(numCourses) if ind[i]==0)
        done=0
        while q:
            c=q.popleft(); done+=1
            for nb in adj[c]:
