class Solution:
    def ladderLength(self, beginWord, endWord, wordList):
        if endWord not in wordList: return 0
        adj=defaultdict(list)
        for w in wordList+[beginWord]:
            for i in range(len(w)): adj[w[:i]+'_'+w[i+1:]].append(w)
        q,vis=deque([(beginWord,1)]),{beginWord}
        while q:
            word,dist=q.popleft()
            for i in range(len(word)):
                for nw in adj[word[:i]+'_'+word[i+1:]]:
                    if nw==endWord: return dist+1
                    if nw not in vis: vis.add(nw); q.append((nw,dist+1))
        return 0

