        for a,b in zip(s,t):
            if (a in st and st[a]!=b) or (b in ts and ts[b]!=a): return False
            st[a],ts[b]=b,a
        return True

class Solution:
    def subarraySum(self, nums, k):
        seen,count,rsum={0:1},0,0
        for n in nums:
            rsum+=n; count+=seen.get(rsum-k,0)
            seen[rsum]=seen.get(rsum,0)+1
        return count

