import heapq
class Solution:
    def mergeKLists(self, lists):
        heap,dummy=[],ListNode(0); curr=dummy
        for i,l in enumerate(lists):
            if l: heapq.heappush(heap,(l.val,i)); lists[i]=l.next
        while heap:
            val,i=heapq.heappop(heap)
            curr.next=ListNode(val); curr=curr.next
            if lists[i]: heapq.heappush(heap,(lists[i].val,i)); lists[i]=lists[i].next
        return dummy.next

class Solution {
    public int minMeetingRooms(int[][] intervals) {
        Arrays.sort(intervals, (a,b)->a[0]-b[0]);
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        heap.add(intervals[0][1]);
        for (int i=1; i<intervals.length; i++) {
            if (intervals[i][0]>=heap.peek()) heap.poll();
            heap.add(intervals[i][1]);
        }
        return heap.size();
    }
