class Solution:
    def findPeakElement(self, nums):
        lo,hi=0,len(nums)-1
        while lo<hi:
            mid=(lo+hi)//2
            if nums[mid]<nums[mid+1]: lo=mid+1
            else: hi=mid
        return lo

class Solution:
    def combinationSum(self, candidates, target):
        res=[]
        def bt(start,path,rem):
            if rem==0: res.append(path[:]); return
            for i in range(start,len(candidates)):
                if candidates[i]>rem: break
                path.append(candidates[i]); bt(i,path,rem-candidates[i]); path.pop()
        candidates.sort(); bt(0,[],target); return res

class Solution:
    def minFallingPathSum(self, matrix):
        n=len(matrix)
        for i in range(n-2,-1,-1):
            for j in range(n):
                best=matrix[i+1][j]
                if j>0: best=min(best,matrix[i+1][j-1])
                if j<n-1: best=min(best,matrix[i+1][j+1])
                matrix[i][j]+=best
        return min(matrix[0])

class Solution:
    def findJudge(self, n, trust):
        score=[0]*(n+1)
        for a,b in trust: score[a]-=1; score[b]+=1
        return next((i for i in range(1,n+1) if score[i]==n-1),-1)

class Solution:
    def numIslands(self, grid):
        m,n,count=len(grid),len(grid[0]),0
        def dfs(i,j):
            if i<0 or i>=m or j<0 or j>=n or grid[i][j]!='1': return
            grid[i][j]='0'
            for di,dj in [(0,1),(1,0),(0,-1),(-1,0)]: dfs(i+di,j+dj)
        for i in range(m):
            for j in range(n):
                if grid[i][j]=='1': dfs(i,j); count+=1
        return count

from collections import defaultdict
class Solution:
    def criticalConnections(self, n, connections):
        adj=defaultdict(list)
        for a,b in connections: adj[a].append(b); adj[b].append(a)
        bridges,arr,low=[], [-1]*n, [-1]*n
        t=[0]
        def dfs(v,par):
            arr[v]=low[v]=t[0]; t[0]+=1
            for nb in adj[v]:
                if nb==par: continue
                if arr[nb]==-1:
                    dfs(nb,v); low[v]=min(low[v],low[nb])
